import { DATA as D } from './data.js';
import { defaults, normalize, model, scenarioQuery } from './model.js';

const $ = (q,root=document)=>root.querySelector(q);
const $$ = (q,root=document)=>[...root.querySelectorAll(q)];
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n=>Number(n).toLocaleString('en-US');
const m = (n,d=1)=>'$'+Number(n).toFixed(d)+'M';
const dollars = n=>'$'+Math.round(n).toLocaleString('en-US');
const color = rating=>({Good:'#428c78',Fair:'#bc9647',Poor:'#bd7055',Critical:'#b8424e'}[rating]||'#7c95a5');
const siteById = id=>D.sites.find(s=>s.id===id);
const badge = (text,cls='')=>`<span class="badge ${cls||String(text).toLowerCase()}">${esc(text)}</span>`;
const source = (page,label)=>`<a class="source" href="${D.report}#page=${page}" target="_blank" rel="noopener" title="Open source report, page ${page}">${label||`Report p. ${page}`} ↗</a>`;
const navs=[['overview','Overview','grid'],['capital','Capital Plan','chart'],['sites','Sites','building'],['energy','Energy','bolt'],['action','Action Plan','check'],['funding','Funding','wallet'],['about','About','info']];
const iconPaths={
  grid:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',
  chart:'<path d="M4 3v17h17M8 15v-4m5 4V7m5 8V4"/>',
  building:'<path d="M4 21V7l8-4 8 4v14M2 21h20M9 21v-5h6v5M8 9h1m6 0h1m-8 3h1m6 0h1"/>',
  bolt:'<path d="m13 2-9 12h7l-1 8 10-13h-7z"/>',
  check:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="m8 12 3 3 5-6"/>',
  wallet:'<path d="M20 8V5H5a2 2 0 0 0 0 4h15v11H5a2 2 0 0 1-2-2V7m17 5h-5v5h5m-3-2.5h.1"/>',
  info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10h.01"/>',
  arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',
  download:'<path d="M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5"/>',
  print:'<path d="M7 8V3h10v5M7 17H3V8h18v9h-4M7 14h10v7H7zM17 11h1"/>',
  layout:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M9 4v16"/>',
  tabs:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 9h18"/>',
  menu:'<path d="M4 6h16M4 12h16M4 18h16"/>',
  share:'<path d="M12 16V3m-5 5 5-5 5 5M5 12H3v9h18v-9h-2"/>',
  chevron:'<path d="m9 5 7 7-7 7"/>',
  left:'<path d="m15 5-7 7 7 7"/>',
  shield:'<path d="m12 3 8 3v6c0 5-8 10-8 10S4 17 4 12V6z"/><path d="m8 12 3 3 5-6"/>',
  reset:'<path d="M4 11a8 8 0 1 1 2 7M4 4v7h7"/>'
};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths.info}</svg>`;
const link = (route,text)=>`<a class="text-link" href="#/${route}">${text} ${icon('arrow')}</a>`;
let currentRoute='overview', currentSite=null;
let scenario={...defaults}, siteSort={key:'fci',direction:-1}, siteType='all';
let filters={q:'',site:'all',priority:'all',system:'all'};
let activeFindings=[],lastModel=null;

function heading(kicker,title,description,actions=''){
  return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${actions?`<div class="heading-tools">${actions}</div>`:''}</div>`;
}
function section(title,description='',right=''){
  return `<div class="section-head"><div><h2>${title}</h2>${description?`<p>${description}</p>`:''}</div>${right}</div>`;
}
function panelHead(title,subtitle,page){
  return `<div class="panel-header"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${page?source(page):''}</div>`;
}
function phases(){
  return `<div class="phase-grid">${D.phases.map((p,i)=>`<article class="phase-card" style="--phase:${['#0879d5','#4f9b9a','#94a9b9'][i]}"><div class="phase-years">PHASE ${i+1} · ${p.years}</div><h3>${p.name}</h3><div class="phase-cost">${m(p.cost)}</div><p>${p.detail}</p></article>`).join('')}</div>`;
}
function portfolioMap(){
  return `<div class="map-frame"><svg class="portfolio-map" viewBox="0 0 540 460" role="img" aria-label="Schematic map of the eight fictional facilities; select a site to open its profile">
  <defs><pattern id="map-grid" patternUnits="userSpaceOnUse" width="30" height="30"><path d="M30 0H0V30" fill="none" stroke="#d9e6e9" stroke-width=".6"/></pattern></defs>
  <rect width="540" height="460" fill="#e5eff2"/><path d="M170-10C151 37 174 74 150 115S155 171 137 214S113 239 96 266S105 320 120 343S155 379 160 416L180 470H560V-10Z" fill="#f6f8f4" stroke="#c5d9d7" stroke-width="1.5"/>
  <path d="M170-10C151 37 174 74 150 115S155 171 137 214S113 239 96 266S105 320 120 343S155 379 160 416L180 470H560V-10Z" fill="url(#map-grid)" opacity=".8"/>
  <path d="M257 0 254 117 284 220 265 326 286 460M150 154 289 154 540 182M124 290 278 290 540 317M170 377 310 377 540 399" fill="none" stroke="#fff" stroke-width="7"/><path d="M257 0 254 117 284 220 265 326 286 460M150 154 289 154 540 182M124 290 278 290 540 317M170 377 310 377 540 399" fill="none" stroke="#d7e1df" stroke-width="1"/>
  <path d="m480 0-25 95-30 50 38 45 70 10" fill="none" stroke="#cce2e4" stroke-width="8"/>
  <text class="map-label" x="65" y="155" transform="rotate(-75 65 155)">GULF COAST</text><text class="map-city" x="350" y="235">MANGROVE BAY</text>
  <g transform="translate(485,375)" stroke="#8b9ca4" fill="none"><path d="M0 33V0m-5 7L0 0l5 7"/></g><text class="map-label" x="481" y="364">N</text>
  ${D.sites.map(s=>{const[x,y]=s.map,r=7+Math.sqrt(s.area/10000)*1.7;return `<a class="map-pin" href="#/sites/${s.id}" aria-label="${esc(s.name)}, ${s.fci}% FCI, ${s.rating}"><title>${s.name} · ${s.fci}% FCI · ${s.rating}${s.shelter?' · EHPA shelter':''}</title>${s.shelter?`<circle cx="${x}" cy="${y}" r="${r+4}" fill="none" stroke="#5c8c81" stroke-width="1.5"/>`:''}<circle cx="${x}" cy="${y}" r="${r}" fill="${color(s.rating)}" stroke="#fff" stroke-width="2.5"/><text x="${x+r+9}" y="${y+4}">${s.code}</text></a>`}).join('')}
  </svg></div><div class="legend"><span><i class="dot" style="--dot:#428c78"></i>Good</span><span><i class="dot" style="--dot:#bc9647"></i>Fair</span><span><i class="dot" style="--dot:#bd7055"></i>Poor</span><span><i class="dot ring"></i>EHPA shelter</span></div><p class="map-note">Illustrative geography · Pin area reflects building size · Select a site</p>`;
}
function rankings(){
  return `<div class="rank-list">${[...D.sites].sort((a,b)=>b.fci-a.fci).map(s=>`<a href="#/sites/${s.id}" class="rank-row"><span class="rank-label">${s.short}</span><div class="rank-track"><div class="rank-fill" style="width:${s.fci/30*100}%;--bar:${color(s.rating)}"></div></div><span class="rank-value" style="color:${color(s.rating)}">${s.fci.toFixed(1)}%</span></a>`).join('')}</div><div class="rank-note"><strong>FCI = current needs ÷ replacement value.</strong><br>A higher percentage means more repair and renewal need relative to the value of the building.</div>`;
}
function overview(){
  const metrics=[['Current needs',m(D.portfolio.current),'Deferred + due by FY27','action'],['Portfolio FCI','9.5<span class="unit">%</span>','Fair · 4 of 8 sites are Poor','sites'],['10-year renewal',m(D.portfolio.renewal),'FY27–FY36 · 2026 dollars','capital'],['Weighted site EUI','50.5','kBtu/sf · FY25','energy'],['Energy cost','$1.70<span class="unit">/sf</span>','Electricity + natural gas','energy'],['Net savings potential','$503<span class="unit">K/yr</span>','Preliminary · before contract M&V','funding']];
  return `<div class="hero"><div class="hero-copy"><div class="eyebrow">Phase 1 <span class="muted">/ Executive companion</span></div><h1>Four of eight sites rate Poor. Three carry 75% of current needs.</h1><p>The portfolio rates <strong>Fair</strong> overall at a 9.5% FCI, but the need is concentrated at Mangrove Bay HS, Westshore HS and Coral Key ES. The eight assessed sites need about <strong>$17.3M a year</strong> after FY27, against $15.1M of renewal millage for all 41 facilities.</p><div class="hero-bottom"><a class="button primary" href="#/capital">Explore the capital plan ${icon('arrow')}</a><span class="hero-meta">8 facilities · 1.20M square feet</span></div></div><div class="hero-photo"><img src="assets/campus.jpeg" alt="Illustrative Florida school campus with palm trees and covered walkways"><span class="hero-tag">2026 FACILITY ASSESSMENT</span><span class="hero-caption">AI-generated illustration from the sample report</span></div></div>
  <div class="metrics">${metrics.map(([label,value,sub,route])=>`<a class="metric" href="#/${route}"><span class="metric-arrow">↗</span><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-sub">${sub}</div></a>`).join('')}</div>
  <div class="overview-grid"><section class="panel">${panelHead('The assessed portfolio','Eight representative facilities. One connected view.',8)}${portfolioMap()}</section><section class="panel">${panelHead('Where condition needs attention','Current Facility Condition Index, highest first',10)}${rankings()}</section></div>
  <div class="capacity-callout">${icon('info')}<p><strong>Eight sites. A district-wide funding constraint.</strong> These facilities need an average of $17.3M/year after FY27. The $15.1M renewal millage is available for <strong>all 41 facilities</strong>.</p>${link('capital','Test a funding scenario')}</div>
  ${section('Four decisions to move forward','Board actions requested in the assessment',source(5))}<div class="decision-grid">${D.decisions.map((d,i)=>`<a class="decision-card" href="#/${d.route}"><div class="decision-top"><span class="decision-number">0${i+1}</span><span class="decision-amount">${d.amount}</span></div><h3>${d.title}</h3><p>${d.description}</p><div class="decision-bottom"><strong>${d.target} ↗</strong><span>${d.owner}</span></div></a>`).join('')}</div><p class="subtle-note">Actions overlap in scope; these amounts are not an additive project total. Coral Key stabilization includes Priority 1 work.</p>
  ${section('The story behind the numbers','Seven findings that shape the capital strategy',source(3,'Report pp. 3–4'))}<div class="accordion-list">${D.takeaways.map(([title,text],i)=>`<details><summary><span class="idx">0${i+1}</span>${title}</summary><p>${text}</p></details>`).join('')}</div>`;
}
function siteTable(){
  let rows=D.sites.filter(s=>siteType==='all'||s.type===siteType);
  rows.sort((a,b)=>(typeof a[siteSort.key]==='number'?a[siteSort.key]-b[siteSort.key]:String(a[siteSort.key]).localeCompare(String(b[siteSort.key])))*siteSort.direction);
  const th=(key,label,right='')=>`<th class="${right}" aria-sort="${siteSort.key===key?(siteSort.direction===1?'ascending':'descending'):'none'}"><button class="sort-button ${siteSort.key===key?'sorted':''}" data-sort="${key}">${label}</button></th>`;
  return `<table class="data-table"><thead><tr>${th('name','Facility')}${th('fci','Current FCI')}${th('current','Current needs','right')}${th('renewal','10-year need','right')}${th('renewalRatio','Need / CRV','right')}${th('eui','Site EUI','right')}<th>Flood zone</th><th>Shelter</th></tr></thead><tbody>${rows.map(s=>`<tr><td><a class="site-name" href="#/sites/${s.id}">${s.name} ↗</a><span class="subtext">${s.type} · ${fmt(s.area)} sf</span></td><td><div class="cell-fci"><span class="mini-track"><span style="width:${s.fci/30*100}%;--bar:${color(s.rating)}"></span></span><strong>${s.fci.toFixed(1)}%</strong></div><span class="subtext" style="color:${color(s.rating)}">${s.rating}</span></td><td class="right">${m(s.current)}</td><td class="right">${m(s.renewal)}</td><td class="right">${s.renewalRatio}%</td><td class="right">${s.eui.toFixed(1)}</td><td>${s.flood}</td><td>${s.shelter?badge('EHPA','good'):'<span class="muted">—</span>'}</td></tr>`).join('')}</tbody>${siteType==='all'?`<tfoot><tr class="table-total"><td>Assessed portfolio</td><td>9.5% · Fair</td><td class="right">$53.3M</td><td class="right">$209.1M</td><td class="right">37%</td><td class="right">50.5</td><td></td><td>3 sites</td></tr></tfoot>`:''}</table>`;
}
function sites(){
  return heading('The portfolio','Eight sites. Eight different needs.','Compare facilities on condition, capital need and energy. Select a school to see its assessment profile.',`<button class="button" data-action="export-sites">${icon('download')}Export sites</button>`)+
  `<div class="toolbar"><div class="field"><label for="site-type">Facility type</label><select id="site-type"><option value="all">All facilities</option>${['Elementary','Middle','High','Support'].map(t=>`<option ${siteType===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="muted small" style="margin-left:auto;align-self:center">${source(9,'Report pp. 9–10')}</div></div><div class="table-wrap" id="site-table">${siteTable()}</div>
  <div class="notice"><strong>Current condition and future renewal are different measures.</strong> FCI describes today’s needs. Ten-year need ÷ replacement value measures cumulative investment, not the condition the building will be in after ten years.</div>`;
}
function simpleBars(values,labels,opts={}){
  const w=760,h=270,left=50,right=20,top=28,bottom=42,pw=w-left-right,ph=h-top-bottom;
  const max=Math.max(1,Math.ceil(Math.max(...values)/5)*5),step=pw/values.length,bw=Math.min(43,step*.62);
  return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="${esc(opts.label||'Annual values')}">${[0,1,2,3,4].map(j=>{const v=max*j/4,y=top+ph-v/max*ph;return `<line class="chart-grid" x1="${left}" x2="${w-right}" y1="${y}" y2="${y}"/><text class="chart-text" x="${left-10}" y="${y+4}" text-anchor="end">${opts.money?'$':''}${v.toFixed(v%1?1:0)}${opts.money?'M':''}</text>`}).join('')}${values.map((v,i)=>{const x=left+step*i+(step-bw)/2,bh=v/max*ph,y=top+ph-bh;return `<g class="chart-bar"><title>${labels[i]}: ${opts.money?m(v,3):v}</title><rect x="${x}" y="${y}" width="${bw}" height="${Math.max(0,bh)}" rx="3" fill="${opts.color||'#0879d5'}"/>${v>0.05?`<text class="chart-amount" x="${x+bw/2}" y="${y-9}" text-anchor="middle">${opts.money?'$':''}${v.toFixed(1)}${opts.money?'M':''}</text>`:''}<text class="chart-text" x="${x+bw/2}" y="${h-17}" text-anchor="middle">${labels[i]}</text></g>`}).join('')}</svg>`;
}
function siteDetail(id){
  const s=siteById(id);if(!s)return notFound();currentSite=s;
  const idx=D.sites.indexOf(s),previous=D.sites[(idx+7)%8],next=D.sites[(idx+1)%8];
  const siteFindings=D.findings.filter(f=>f.site===s.id);
  return `<div class="breadcrumb"><a href="#/sites">Sites</a><span>/</span><span>${s.name}</span></div>`+
  heading(`Facility profile · ${s.code}`,s.name,`${s.type} · ${fmt(s.area)} square feet · ${s.quadrant}`,`<div class="site-switcher"><a class="icon-button" href="#/sites/${previous.id}" aria-label="Previous site: ${previous.name}">${icon('left')}</a><select id="site-switcher" aria-label="Choose a facility">${D.sites.map(t=>`<option value="${t.id}" ${s.id===t.id?'selected':''}>${t.name}</option>`).join('')}</select><a class="icon-button" href="#/sites/${next.id}" aria-label="Next site: ${next.name}">${icon('chevron')}</a></div>`)+
  `<div class="site-metrics">${[['Current FCI',`${s.fci.toFixed(1)}%`,`${s.rating} · portfolio 9.5%`],['Current needs',m(s.current),'Deferred + due by FY27'],['10-year renewal',m(s.renewal),`${s.renewalRatio}% of replacement value`],['Site EUI',s.eui.toFixed(1),'kBtu/sf · portfolio 50.5']].map(([label,value,sub])=>`<div class="stat"><div class="stat-label">${label}</div><div class="stat-value">${value}</div><div class="stat-description">${sub}</div></div>`).join('')}</div>
  <div class="site-profile"><section class="panel">${panelHead('At a glance','Building profile',9)}<dl class="profile-fields">${[['Year built',s.built],['Last major renovation',s.renovation],['Grades',s.grades],['Enrollment',s.enrollment?fmt(s.enrollment):'Not applicable'],['Gross area',fmt(s.area)+' sf'],['Replacement value',m(s.crv)],['Flood zone',s.flood],['EHPA shelter',s.shelter?'Yes':'No'],...(s.id==='coral-key'?[['Site area','11.2 acres']]:[])].map(([t,v])=>`<div><dt>${t}</dt><dd>${v}</dd></div>`).join('')}</dl></section>${s.id==='coral-key'?`<div><img class="site-photo" src="assets/coral-key.jpeg" alt="Illustration of Coral Key Elementary’s covered walkways and low-rise buildings"><p class="photo-note">AI-generated illustration from the fictional sample report</p></div>`:`<div class="profile-context"><div class="code-large">${s.code}</div><p>${s.quadrant}</p><span>${badge(s.rating)} ${s.shelter?badge('EHPA shelter','blue'):''}</span></div>`}</div>
  <div class="grid-two"><section class="panel">${panelHead('Assessment perspective','Summary of the published findings',s.source)}<p class="site-summary">${s.summary}</p><div class="recommendation"><strong>Primary path</strong>${s.path}</div></section><section class="panel">${panelHead('Energy in context','FY25 · compared with the assessed portfolio',13)}${comparison('Site energy use intensity',s.eui,50.5,70,'kBtu/sf')}${comparison('Total utility cost',s.utilityCost,2.04,3,'$/sf')}<p class="subtle-note">Utility cost includes water and sewer. District energy-only cost is $1.70/sf. Usage is billed, not weather-normalized.</p></section></div>
  ${s.id==='coral-key'?`<div class="notice amber"><strong>Stabilize, then decide.</strong> Proceed with $1.2M of essential work; hold $6.2M of renewal scope pending a 30-year replace-versus-renovate study. The separate $300K interim roof allowance is excluded from the $14.7M renewal total. ${source(44)}</div><section class="panel">${panelHead('Coral Key’s renewal profile','Derived from published budget years · 2026 dollars',46)}${simpleBars(D.coralAnnual,D.years,{money:true,label:'Coral Key renewal profile by fiscal year'})}<p class="subtle-note">The $14.720M component-level total rounds to $14.7M. FY27 includes $65K of accessibility and sprinkler repairs. The profile remains the report baseline while the study is pending.</p></section>`:`<div class="notice"><strong>Profile coverage.</strong> This sample includes a summary for ${s.short}. A component-level inventory and annual site renewal schedule are not included in the supplied PDF. The portfolio and site totals shown above are published report values.</div>`}
  ${section('Published findings for this facility',`${siteFindings.length} findings in the supplied report`,link(`action?site=${s.id}`,'Open in Action Plan'))}<div class="table-wrap">${findingsTable(siteFindings,true)}</div>`;
}
function comparison(label,value,average,max,unit){
  const v=unit==='$/sf'?`$${value.toFixed(2)}/sf`:`${value.toFixed(1)} ${unit}`,a=unit==='$/sf'?`$${average.toFixed(2)}/sf`:`${average.toFixed(1)} ${unit}`;
  return `<div class="comparison-row"><div class="comparison-head"><span>${label}</span><strong>${v}</strong></div><div class="comparison-track"><span style="width:${value/max*100}%"></span></div><div class="comparison-head muted" style="margin-top:7px;font-size:10px"><span>Portfolio average</span><span>${a}</span></div></div>`;
}
function notFound(){return heading('Assessment companion','This page isn’t available.','Choose an assessment section to continue.',`<a class="button primary" href="#/overview">Back to overview</a>`);}

function quadrant(){
  const x=v=>58+v/30*660,y=v=>325-(v-30)/35*280;
  const labels={'coral-key':[-8,-25,'middle'],'pelican-point':[20,5,'start'],'heron-creek':[0,27,'middle'],'bayside':[20,-7,'start'],'tarpon-ridge':[17,-20,'start'],'mangrove-bay-high':[4,-29,'middle'],'westshore':[-15,29,'middle'],'operations-center':[20,7,'start']};
  return `<svg class="chart-svg quadrant-chart" viewBox="0 0 760 390" role="img" aria-label="Interactive condition versus energy chart; select a facility bubble for its profile"><rect x="58" y="45" width="110" height="120" fill="#ecf5f1"/><rect x="168" y="45" width="550" height="120" fill="#eef4f9"/><rect x="58" y="165" width="110" height="160" fill="#f1f7f4"/><rect x="168" y="165" width="550" height="160" fill="#f6f7f5"/>
  ${[30,40,50,60].map(v=>`<line x1="58" x2="718" y1="${y(v)}" y2="${y(v)}" class="chart-grid"/><text x="44" y="${y(v)+4}" class="chart-text" text-anchor="end">${v}</text>`).join('')}
  ${[0,5,10,15,20,25,30].map(v=>`<text class="chart-text" x="${x(v)}" y="349" text-anchor="middle">${v}%</text>`).join('')}
  <line x1="${x(5)}" x2="${x(5)}" y1="45" y2="325" stroke="#a9bdc4" stroke-dasharray="4 5"/><line x1="58" x2="718" y1="${y(50)}" y2="${y(50)}" stroke="#a9bdc4" stroke-dasharray="4 5"/>
  <text class="quadrant-title" x="63" y="29">OPTIMIZE</text><text class="quadrant-title" x="711" y="29" text-anchor="end">RENEW & RETROFIT</text><text class="quadrant-title" x="63" y="378">MAINTAIN</text><text class="quadrant-title" x="711" y="378" text-anchor="end">CAPITAL RENEWAL</text>
  <text class="chart-text" x="388" y="377" text-anchor="middle">Current FCI →</text><text class="chart-text" x="14" y="195" text-anchor="middle" transform="rotate(-90 14 195)">Site EUI · kBtu/sf</text>
  ${D.sites.map(s=>{const[dx,dy,anchor]=labels[s.id],r=6+Math.sqrt(s.area/10000)*2.3;return `<a class="bubble" href="#/sites/${s.id}" aria-label="${s.name}, FCI ${s.fci}%, EUI ${s.eui}"><title>${s.name} · FCI ${s.fci}% · EUI ${s.eui} · ${s.quadrant}</title><circle cx="${x(s.fci)}" cy="${y(s.eui)}" r="${r}" fill="${color(s.rating)}" opacity=".8" stroke="white" stroke-width="2"/><text x="${x(s.fci)+dx}" y="${y(s.eui)+dy}" text-anchor="${anchor}">${s.short}</text></a>`}).join('')}</svg>`;
}
function trendChart(){
  const usage=D.trends.electricity.map(v=>v/D.trends.electricity[0]*100),cost=D.trends.utility.map(v=>v/D.trends.utility[0]*100);
  const x=i=>55+i*185,y=v=>211-(v-90)/30*168;
  const series=[{v:usage,color:'#0879d5',label:'Electricity use'},{v:cost,color:'#4f9b9a',label:'Total utility cost'}];
  return `<svg class="chart-svg" viewBox="0 0 670 265" role="img" aria-label="Electricity consumption declined while total utility cost increased from FY22 to FY25; FY22 equals 100">${[90,100,110,120].map(v=>`<line x1="55" x2="612" y1="${y(v)}" y2="${y(v)}" class="chart-grid"/><text class="chart-text" x="40" y="${y(v)+4}" text-anchor="end">${v}</text>`).join('')}${series.map(s=>`<path d="${s.v.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ')}" stroke="${s.color}" stroke-width="2.5" fill="none"/>${s.v.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="4" fill="white" stroke="${s.color}" stroke-width="2"><title>${s.label} · ${D.trends.years[i]} · ${v.toFixed(1)} (FY22 = 100)</title></circle>`).join('')}`).join('')}${D.trends.years.map((v,i)=>`<text class="chart-text" x="${x(i)}" y="244" text-anchor="middle">${v}</text>`).join('')}</svg><div class="chart-key"><span><i style="--key:#0879d5"></i>Electricity use</span><span><i style="--key:#4f9b9a"></i>Total utility cost</span><span>FY22 = 100</span></div>`;
}
function energy(){
  return heading('Energy & performance','Condition is only half the picture.','Pair facility condition with energy use to identify where to renew, where to tune, and where to maintain.')+
  `<div class="energy-hero"><div class="stat"><div class="stat-label">Electricity use · FY22–FY25</div><div class="stat-value" style="color:#347d68">−3.2%</div><div class="stat-description">16.85M kWh in FY25</div></div><div class="stat"><div class="stat-label">Total utility cost · FY22–FY25</div><div class="stat-value">+9.7%</div><div class="stat-description">$2.44M in FY25</div></div><div class="energy-insight"><strong>Usage is down. Bills are up.</strong> Rate increases offset lower consumption. The district can influence use even when it cannot control rates.<br>${source(12)}</div></div>
  <div class="quadrant-layout"><section class="panel">${panelHead('Where to act—and how','Select a bubble to open a facility. Size reflects building area.',15)}${quadrant()}<div class="legend"><span><i class="dot" style="--dot:#428c78"></i>Good FCI</span><span><i class="dot" style="--dot:#bc9647"></i>Fair FCI</span><span><i class="dot" style="--dot:#bd7055"></i>Poor FCI</span></div><p class="subtle-note">Quadrant splits: 5% FCI and 50 kBtu/sf. The ENERGY STAR national K–12 median of 48.5 is a reference, not a Florida-specific target.</p></section><section class="panel">${panelHead('Energy cost benchmarks','Electricity + natural gas · FY25 $/sf',15)}${[['Mangrove Bay',1.70,true],['Collier',1.61],['Pinellas',1.53],['Charlotte',1.41],['Florida statewide',1.35]].map(([label,v,highlight])=>`<div class="benchmark ${highlight?'highlight':''}"><div class="benchmark-label"><span>${label}</span><span>$${v.toFixed(2)}</span></div><div class="benchmark-bar"><span style="width:${v/1.9*100}%"></span></div></div>`).join('')}<p class="subtle-note">Report benchmark: 26% above statewide energy cost. Building-area definitions differ, so comparisons are directional.</p><div class="notice" style="margin-bottom:0">Portfolio total utility cost is <strong>$2.04/sf</strong> when water and sewer are included.</div></section></div>
  <div class="grid-two"><section class="panel">${panelHead('Consumption versus cost','Four years of billed data · not weather-normalized',12)}${trendChart()}</section><section class="panel">${panelHead('Preliminary net savings','$503K/year across all modeled measures',3)}${D.savings.map(([name,v,c])=>`<div class="benchmark"><div class="benchmark-label"><span>${name}</span><span>$${v}K/yr</span></div><div class="benchmark-bar"><span style="width:${v/164*100}%;background:${c}"></span></div></div>`).join('')}<p class="subtle-note">After monitoring fees and solar O&M; before performance-contract M&V. Estimated savings are not guarantees. ${link('funding','See the funding package')}</p></section></div>
  <div class="energy-opportunity"><div class="panel-header"><div><div class="eyebrow" style="color:#377d67">An immediate opportunity</div><h2>Tarpon Ridge: investigate operations first.</h2></div>${link('sites/tarpon-ridge','View site')}</div><div class="grid-three"><div><div class="stat-value">0.2%</div><p>FCI · best condition in the portfolio</p></div><div><div class="stat-value">$124K</div><p>Retro-commissioning, including economizer repairs</p></div><div><div class="stat-value">3.6 years</div><p>Estimated simple payback at $35K annual savings</p></div></div><p style="margin-bottom:0">The report records 41% of air handlers in hand and about 62 hours per week of runtime beyond occupancy. Validate occupancy, ventilation, schedules and equipment performance before attributing the cause. This scope proceeds outside the performance contract.</p></div>`;
}
function findingsTable(items,compact=false){
  return `<table class="data-table findings-table"><thead><tr><th>Finding</th>${compact?'':'<th>Facility</th>'}<th>Priority / timing</th><th>System & scope</th><th class="right">Project cost</th><th>Source</th></tr></thead><tbody>${items.length?items.map(f=>`<tr><td><span class="id-label">${f.id}</span><div class="finding-title">${f.title}</div></td>${compact?'':`<td><a href="#/sites/${f.site}">${siteById(f.site).short} ↗</a></td>`}<td>${badge('Priority '+f.priority,'p'+f.priority)}<span class="subtext">${f.year}</span>${f.hold?'<span class="hold-note">On hold · Coral Key study</span>':''}</td><td><strong class="small" style="font-size:10px">${f.system}</strong><div class="finding-scope">${f.scope}</div></td><td class="right finding-cost">${dollars(f.cost)}</td><td>${source(f.page,'p. '+f.page)}</td></tr>`).join(''):`<tr><td colspan="${compact?5:6}" class="empty">No published findings match these filters. Adjust the filters or clear them to see all findings.</td></tr>`}</tbody></table>`;
}
function filteredFindings(){
  const q=filters.q.trim().toLowerCase();
  return D.findings.filter(f=>(filters.site==='all'||f.site===filters.site)&&(filters.priority==='all'||String(f.priority)===filters.priority)&&(filters.system==='all'||f.system===filters.system)&&(!q||[f.id,f.title,f.scope,f.system,siteById(f.site).name].join(' ').toLowerCase().includes(q)));
}
function findingCount(items){return `<span><strong>${items.length}</strong> published findings <span class="muted">/ 24 available</span></span><span>Filtered project cost <strong>${dollars(items.reduce((a,f)=>a+f.cost,0))}</strong></span>`;}
function action(){
  const sum=p=>D.findings.filter(f=>f.priority===p).reduce((a,f)=>a+f.cost,0)/1e6;
  activeFindings=filteredFindings();
  return heading('Prioritized action plan','The right work, in the right order.','Explore the report’s published findings by facility, system and consequence of failure.')+
  `<div class="priority-grid">${[['Immediate','FY27',8],['Near-term','FY27–FY28',14],['Planned','FY29–FY31',1],['Deferred','FY32–FY36',1]].map(([label,year,count],i)=>`<button class="priority-card ${filters.priority===String(i+1)?'selected':''}" data-priority="${i+1}" aria-pressed="${filters.priority===String(i+1)}">${badge(`P${i+1} · ${label}`,'p'+(i+1))}<div class="stat-value"${i>1?' style="font-size:19px;line-height:1.55"':''}>${i>1?'Not itemized':m(sum(i+1),1)}</div><p>${i>1?`Phase 1 itemizes P1–P2 · ${count} example shown · ${year}`:`${count} published findings · ${year}`}</p></button>`).join('')}</div>
  <div class="notice"><strong>A focused findings register.</strong> All 22 Priority 1–2 findings are included, plus the two additional Coral Key findings published in the sample. Priority 3–4 work is not itemized in Phase 1; it sits inside the age-based renewal forecast, as do all listed costs.</div>
  <div class="toolbar"><div class="field search"><label for="finding-search">Search findings</label><input type="search" id="finding-search" placeholder="Search a finding, system or facility…" value="${esc(filters.q)}"></div><div class="field"><label for="finding-site">Facility</label><select id="finding-site"><option value="all">All facilities</option>${D.sites.map(s=>`<option value="${s.id}" ${filters.site===s.id?'selected':''}>${s.short}</option>`).join('')}</select></div><div class="field"><label for="finding-priority">Priority</label><select id="finding-priority"><option value="all">All priorities</option>${[1,2,3,4].map(p=>`<option value="${p}" ${filters.priority===String(p)?'selected':''}>Priority ${p}</option>`).join('')}</select></div><div class="field"><label for="finding-system">System</label><select id="finding-system"><option value="all">All systems</option>${[...new Set(D.findings.map(f=>f.system))].sort().map(s=>`<option ${filters.system===s?'selected':''}>${s}</option>`).join('')}</select></div><button class="button" data-action="clear-filters">Clear</button><button class="button" data-action="export-findings">${icon('download')}Export</button></div>
  <div class="count-line" id="finding-count" aria-live="polite">${findingCount(activeFindings)}</div><div class="table-wrap" id="findings-table">${findingsTable(activeFindings)}</div><p class="subtle-note">Project costs are 2026 planning estimates. The $7.2M and $19.7M priority headlines are rounded; exports retain the published item-level costs.</p>
  ${section('A phased capital program','Phase totals include lifecycle renewals as well as deficiency work.',source(40))}${phases()}
  ${section('From board action to construction','Report sequence; actual dates follow approvals and procurement.',source(41))}<div class="panel"><ol class="method-list"><li><strong>Weeks 0–4 · Confirm the program</strong>Board briefing, priorities workshop, Phase 1 scope and funding plan.</li><li><strong>Weeks 0–12 · Stabilize and investigate</strong>Fund Priority 1, establish interim risk controls and begin Tarpon Ridge retro-commissioning.</li><li><strong>Weeks 4–20 · Resolve the major decisions</strong>Complete the Coral Key study and the HVAC / controls investment-grade audit. Order long-lead equipment as scopes are approved.</li><li><strong>Weeks 20–32 · Approve contracts</strong>Review guarantee terms, financing and capital project awards.</li><li style="padding-bottom:0"><strong>Summer 2027 onward · Deliver and verify</strong>Schedule permanent replacements in low-occupancy windows, commission completed work and verify savings.</li></ol></div>`;
}
function funding(){
  return heading('Funding strategy','Match the funding to the need.','Capital renewal carries the program. Efficiency savings help fund better outcomes on work that is already needed.')+
  `<div class="funding-intro"><div><div class="eyebrow">The report’s central funding finding</div><h2>A performance contract is a delivery tool, not a funding source.</h2><p>The proposed package combines essential equipment renewal with efficiency improvements and verified savings. It still needs substantial district capital.</p></div><div class="stat"><div class="stat-label">Capital still required for the package</div><div class="funding-amount">$16.3M</div><div class="stat-description">Of $19.8M total project cost · ${source(36)}</div></div></div>
  <div class="grid-two"><section class="panel">${panelHead('What is in the $19.8M package?','Base replacement plus the efficiency investment',36)}<div class="funding-stack"><span style="width:${14.9/19.8*100}%;background:#426782">$14.9M</span><span style="width:${2.2/19.8*100}%;background:#0879d5"></span><span style="width:${2.1/19.8*100}%;background:#4f9b9a"></span><span style="width:${.6/19.8*100}%;background:#aabccd"></span></div><div class="stack-legend">${[['Like-for-like renewal',14.9,'#426782'],['Efficiency premiums',2.2,'#0879d5'],['Standalone measures',2.1,'#4f9b9a'],['Audit & development',.6,'#aabccd']].map(([label,v,c])=>`<span><i class="dot" style="--dot:${c}"></i>${label}<b>${m(v)}</b></span>`).join('')}</div><div class="notice" style="margin-bottom:0"><strong>$4.9M is the efficiency investment.</strong> That includes premiums, standalone measures, and audit / development. The underlying $14.9M renewal need remains.</div></section><section class="panel">${panelHead('What can savings support?','Illustrative report financing assumptions',36)}${[['Estimated net annual savings','$344K'],['Guaranteed savings, after M&V','$284K'],['Savings-supported financing','$3.5M'],['Capital funding still required','$16.3M']].map(([label,v],i)=>`<div class="waterfall-row ${i===3?'emphasis':''}"><span>${label}</span><strong>${v}</strong></div>`).join('')}<p class="subtle-note">20 years at 5% · 85% savings guarantee · M&V at 3% of guaranteed savings. Financing supports about 72% of the efficiency cost. These are report scenarios, not financing offers.</p></section></div>
  ${section('The capital funding picture','Report assumptions for the fictional district; confirm eligibility before committing funds.',source(7))}<div class="source-cards"><article class="source-card"><h3>Capital outlay millage</h3><div class="source-value">$15.1M<span class="small"> / year</span></div><p>Available for renewal across all 41 facilities, after other commitments against the $43.2M gross annual levy.</p><span class="tag">Primary recurring capacity</span></article><article class="source-card"><h3>Half-cent sales surtax</h3><div class="source-value">$22.0M<span class="small"> / year</span></div><p>The sample’s 2024 referendum limits use to new construction and major renovation through 2034. A potential fit for Coral Key.</p><span class="tag">Scope-limited capital</span></article><article class="source-card"><h3>PECO maintenance</h3><div class="source-value">Not assumed</div><p>The report does not treat PECO as a dependable planning source. Unawarded grants and rebates are also outside committed funding.</p><span class="tag">No committed capacity modeled</span></article></div>
  <div class="capacity-callout">${icon('chart')}<p><strong>What funding level changes the trajectory?</strong> Test the annual allocation, construction inflation and Coral Key assumptions against the assessed renewal forecast.</p>${link('capital','Open the scenario model')}</div>
  ${section('The improvement measures','Preliminary modeled savings; payback is on the efficiency cost, not full installed cost.',source(34))}<div class="table-wrap"><table class="data-table"><thead><tr><th>Measure</th><th class="right">Installed cost</th><th class="right">Efficiency cost</th><th class="right">Net savings / yr</th><th class="right">Payback · years</th><th>Performance package</th></tr></thead><tbody>${D.measures.map(([id,name,cost,eff,savings,payback,included])=>`<tr><td><span class="id-label">${id}</span> <span style="font-weight:500">${name}</span></td><td class="right">${m(cost)}</td><td class="right">${m(eff)}</td><td class="right">$${savings}K</td><td class="right">${payback}</td><td>${included==='Included'?badge(included,'blue'):included}</td></tr>`).join('')}</tbody><tfoot><tr class="table-total"><td>Report total</td><td class="right">$47.6M</td><td class="right">$9.9M</td><td class="right">$503K</td><td></td><td></td></tr></tfoot></table></div><p class="subtle-note">Rounded rows may differ from totals. Net savings are after monitoring fees and solar O&M, before performance-contract M&V. Tarpon Ridge’s $124K commissioning scope and approximately $35K/year savings are outside the contract baseline.</p>
  <div class="notice amber"><strong>Avoid double counting.</strong> Most of the $47.6M measure catalog overlaps the $209.1M renewal forecast. The report identifies $3.3M of additions, producing about $212.4M before escalation and any Coral Key replacement decision. The scenario model uses the $209.1M renewal forecast; it does not automatically add the separate program allowances. ${source(35)}</div>`;
}
function about(){
  return heading('Scope & methodology','A shared basis for better decisions.','What this assessment covers, how to read the numbers, and where the sample’s detail ends.',`<a class="button" href="${D.report}" download>${icon('download')}Download the full report</a>`)+
  `<div class="notice"><strong>A fictional district. A representative deliverable.</strong> Mangrove Bay, its facilities, findings, costs and assessment team were created to illustrate Upchurch’s FCA deliverable. This website is a fixed companion to the report, not a live maintenance system.</div>
  <div class="about-grid"><section class="panel">${panelHead('What was assessed','Phase 1 · 8 of 41 facilities',53)}<ol class="method-list"><li><strong>Records and field observation</strong>District records, 36 months of work orders, four fiscal years of utility bills, site interviews and building walk-throughs.</li><li><strong>Component-level assessment</strong>Major systems organized by UNIFORMAT II; install year, useful life, observed condition and remaining life recorded. Age alone is not an instruction to replace functioning equipment.</li><li><strong>Quantities and planning costs</strong>Major scopes priced from quantities and Florida-adjusted 2026 unit costs. A 1.30× construction multiplier includes project costs.</li><li><strong>Energy and consequence of failure</strong>Utility benchmarking, sequential savings estimates, deficiencies and recommended actions combine to set priorities.</li><li style="padding-bottom:0"><strong>A phased renewal program</strong>Needs sequenced through FY36. The other 33 facilities require assessment before a district-wide need can be stated.</li></ol></section><div><section class="panel">${panelHead('Reading condition','Facility Condition Index: current needs ÷ CRV',54)}<div class="rating-list">${[['Good','≤5%','Routine maintenance and planned renewals'],['Fair','>5–10%','Plan funding as renewals come due'],['Poor','>10–30%','Needs affect reliability and occupants'],['Critical','>30%','Evaluate major renovation or replacement']].map(([r,b,t])=>`<div class="rating-item">${badge(r)}<strong>${b}</strong><span>${t}</span></div>`).join('')}</div><p class="subtle-note">FCI is a cost ratio. Observed component condition and consequence of failure require separate judgment.</p></section><section class="panel" style="margin-top:23px">${panelHead('Cost basis','Planning estimates, not construction bids',55)}<div class="waterfall-row"><span>Base year</span><strong>2026 dollars</strong></div><div class="waterfall-row"><span>Planning accuracy</span><strong>±25%</strong></div><div class="waterfall-row"><span>Project-cost multiplier</span><strong>1.30×</strong></div><div class="waterfall-row"><span>Report escalation scenario</span><strong>4% / year</strong></div><p class="subtle-note">CRV excludes land, FF&E, demolition and temporary housing. Project design refines scope, pricing and code requirements.</p></section></div></div>
  ${section('A few useful definitions')}<div class="panel"><dl class="glossary">${[['FCI · Facility Condition Index','Current needs divided by current replacement value. The report’s current portfolio FCI is 9.5%.'],['CRV · Current replacement value','The estimated project cost to replace the facility in kind on the report’s defined cost basis.'],['Site EUI · Energy use intensity','Energy consumed at the site per square foot, in kBtu/sf per year. This is different from energy cost.'],['EHPA · Enhanced Hurricane Protection Area','A designated hurricane-shelter function. The shelter depends on systems operating together during an event.'],['RCx · Retro-commissioning','Investigation and correction of operating sequences, controls and system performance in existing buildings.'],['M&V · Measurement and verification','Measurement used to determine and verify the achieved energy savings after project implementation.']].map(([t,d])=>`<div><dt>${t}</dt><dd>${d}</dd></div>`).join('')}</dl></div>
  ${section('Source coverage and interpretation','The source report remains the assessment record.',source(2))}<div class="panel"><ul class="coverage-notes">${D.sourceNotes.map(t=>`<li>${t}</li>`).join('')}</ul><div class="notice" style="margin-bottom:0"><strong>Scenario outputs are projections.</strong> The model rolls forward unfunded renewal need using your assumptions. Its unfunded-need / CRV ratio is a financial proxy, not a reassessment of actual building condition. Read the model notes on the Capital Plan page before using a scenario.</div></div>
  ${section('Prepared by Upchurch','Facility Consulting · Assessment period: August–September 2026')}<div class="panel"><p class="small muted">Illustrative assessment team named in the sample report</p><div class="team"><div>Dana Whitfield, AIA<span>Architect</span></div><div>Marcus Okafor, PE<span>Mechanical engineer</span></div><div>Elena Ruiz, PE<span>Electrical engineer</span></div></div></div>`;
}

function capitalControls(){
  return `<aside class="panel scenario-controls" aria-label="Scenario assumptions"><h2>Your planning scenario</h2><p class="muted">Change an assumption. See the effect.</p><div class="controls-grid">
  <div class="control-group"><div class="control-heading"><label for="funding-input">Annual allocation</label><div class="input-unit"><span>$</span><input id="funding-input" data-scenario="funding" type="number" min="0" max="60" step="0.1" value="${scenario.funding}" aria-label="Annual funding allocated to eight assessed sites, millions of dollars"><span>M</span></div></div><input id="funding-range" data-scenario="funding" type="range" min="0" max="60" step="0.1" value="${scenario.funding}" aria-label="Annual funding allocation"><div class="range-labels"><span>$0M</span><span>$30M</span><span>$60M</span></div><p class="control-help">For these eight facilities only. $15.1M is the renewal millage available to <strong>all 41 sites</strong>; allocating all of it here is a test case.</p></div>
  <div class="control-group"><div class="control-heading"><label for="inflation-input">Construction inflation</label><div class="input-unit"><input id="inflation-input" data-scenario="inflation" type="number" min="0" max="10" step="0.5" value="${scenario.inflation}" aria-label="Annual construction inflation percent"><span>%</span></div></div><input id="inflation-range" data-scenario="inflation" type="range" min="0" max="10" step="0.5" value="${scenario.inflation}" aria-label="Construction inflation"><div class="range-labels"><span>0%</span><span>5%</span><span>10%</span></div><p class="control-help">Applied to scheduled renewals and carried backlog. The report illustration uses 4%.</p></div>
  <div class="control-group"><div class="field"><label for="start-input">First year of funding</label><select id="start-input" data-scenario="start"><option value="2027" ${scenario.start===2027?'selected':''}>FY27 · report starting year</option><option value="2028" ${scenario.start===2028?'selected':''}>FY28 · one-year delay</option></select></div><p class="control-help">A delay tests the cost of unfunded work; it does not resolve immediate safety or reliability needs.</p></div>
  <div class="control-group"><div class="field"><label for="coral-input">Coral Key pathway</label><select id="coral-input" data-scenario="coral"><option value="undecided" ${scenario.coral==='undecided'?'selected':''}>Study pending</option><option value="renovate" ${scenario.coral==='renovate'?'selected':''}>Retain & renew</option><option value="replace" ${scenario.coral==='replace'?'selected':''}>Replace · enter an allowance</option></select></div><p class="control-help">${scenario.coral==='replace'?'The report does not price replacement. Enter a 2026-dollar, all-in capital allowance.':'The published renewal baseline remains in the forecast. $6.2M is on hold pending the study, not removed from the need.'}</p>${scenario.coral==='replace'?`<div class="field" style="margin-top:12px"><label for="replacement-input">Replacement allowance · $M</label><input id="replacement-input" data-scenario="replacement" type="number" min="0.1" max="150" step="0.1" value="${scenario.replacement??''}" placeholder="Enter study estimate"></div><div class="field" style="margin-top:12px"><label for="replacement-year">Replacement expenditure year</label><select id="replacement-year" data-scenario="replacementYear">${[2028,2029,2030,2031].map(y=>`<option value="${y}" ${scenario.replacementYear===y?'selected':''}>FY${String(y).slice(-2)}</option>`).join('')}</select></div>`:''}</div></div>
  <div class="control-bottom"><button class="button" data-action="reset-model">${icon('reset')}Reset</button><button class="button primary" data-action="share-model">${icon('share')}Share scenario</button></div></aside>`;
}
function annualChart(result){
  const constant=result.scenario.dollars==='constant', w=790,h=295,l=55,r=18,t=32,b=45,pw=w-l-r,ph=h-t-b;
  const values=result.rows.map(row=>constant?row.base:row.due),funds=result.rows.map(row=>constant?row.allocation/row.factor:row.allocation),max=Math.max(10,Math.ceil(Math.max(...values,...funds)/10)*10),step=pw/10,bw=step*.58;
  const scale=v=>t+ph-v/max*ph;
  const coral=result.rows.map((row,i)=>{
    const baseline=result.replacementActive?((i===0?1.5:0)+(row.year===result.scenario.replacementYear?result.scenario.replacement:0)):D.coralAnnual[i];
    return baseline*(constant?1:row.factor);
  });
  return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Annual renewal need and assumed funding for the eight assessed facilities">${[0,1,2,3,4].map(j=>{const v=max*j/4,y=scale(v);return `<line class="chart-grid" x1="${l}" x2="${w-r}" y1="${y}" y2="${y}"/><text class="chart-text" x="${l-9}" y="${y+4}" text-anchor="end">$${v.toFixed(v%1?1:0)}M</text>`}).join('')}
  ${values.map((v,i)=>{const x=l+step*i+(step-bw)/2,other=v-coral[i];return `<g class="chart-bar"><title>${D.years[i]} · need ${m(v,2)} · allocation ${m(funds[i],2)}${constant?' in 2026 dollars':''}</title><rect x="${x}" y="${scale(other)}" width="${bw}" height="${other/max*ph}" fill="#0879d5"/><rect x="${x}" y="${scale(v)}" width="${bw}" height="${coral[i]/max*ph}" fill="#79aba5" rx="2"/><text class="chart-amount" x="${x+bw/2}" y="${scale(v)-9}" text-anchor="middle">${v.toFixed(1)}</text><text class="chart-text" x="${x+bw/2}" y="${h-18}" text-anchor="middle">${D.years[i]}</text></g>`}).join('')}
  <path d="${funds.map((v,i)=>`${i?'L':'M'}${l+step*i+step/2} ${scale(v)}`).join(' ')}" fill="none" stroke="#29495e" stroke-width="2" stroke-dasharray="5 4"/>
  </svg><div class="chart-key"><span><i style="--key:#0879d5"></i>Other seven sites</span><span><i style="--key:#79aba5"></i>Coral Key${result.replacementActive?' scenario':''}</span><span><i class="line-key" style="--key:#29495e"></i>Assumed annual allocation</span></div>`;
}
function backlogChart(result){
  const constant=result.scenario.dollars==='constant',values=result.rows.map(row=>row.backlog/(constant?row.factor:1)),w=790,h=240,l=55,r=18,t=25,b=40,pw=w-l-r,ph=h-t-b;
  const max=Math.max(10,Math.ceil(Math.max(...values)/10)*10),x=i=>l+i*pw/9,y=v=>t+ph-v/max*ph;
  const path=values.map((v,i)=>`${i?'L':'M'}${x(i)} ${y(v)}`).join(' ');
  return `<svg class="chart-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Projected unfunded renewal need at the end of each fiscal year"><defs><linearGradient id="backlog-fill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#0879d5" stop-opacity=".18"/><stop offset="100%" stop-color="#0879d5" stop-opacity=".015"/></linearGradient></defs>${[0,1,2,3,4].map(j=>{const v=max*j/4;return `<line class="chart-grid" x1="${l}" x2="${w-r}" y1="${y(v)}" y2="${y(v)}"/><text class="chart-text" x="${l-9}" y="${y(v)+4}" text-anchor="end">$${v.toFixed(v%1?1:0)}M</text>`}).join('')}<path d="${path} L${x(9)} ${y(0)} L${x(0)} ${y(0)}Z" fill="url(#backlog-fill)"/><path d="${path}" fill="none" stroke="#0879d5" stroke-width="2.4"/>${values.map((v,i)=>`<circle cx="${x(i)}" cy="${y(v)}" r="3.6" fill="#fff" stroke="#0879d5" stroke-width="2"><title>${D.years[i]} · unfunded need ${m(v,2)} · need / indexed CRV ${result.rows[i].ratio.toFixed(1)}%</title></circle><text class="chart-text" x="${x(i)}" y="${h-15}" text-anchor="middle">${D.years[i]}</text>`).join('')}</svg>`;
}
function capitalOutputs(){
  const result=model(scenario);lastModel=result;
  if(!result.valid)return `<div class="projection-error">${icon('info')}<h2 style="margin-top:15px">Add the study’s replacement allowance.</h2><p>${result.error}</p><p class="small">Choose “Study pending” to return to the report’s $209.1M renewal baseline.</p></div>`;
  const constant=scenario.dollars==='constant',end=result.endBacklog/(constant?result.rows.at(-1).factor:1);
  return `<div class="model-banner"><span>${badge('SCENARIO PROJECTION','blue')} <span style="margin-left:6px">For the 8 assessed facilities</span></span><div class="segmented" aria-label="Chart dollar basis"><button data-dollar="constant" class="${constant?'active':''}" aria-pressed="${constant}">2026 dollars</button><button data-dollar="nominal" class="${!constant?'active':''}" aria-pressed="${!constant}">Future dollars</button></div></div>
  <div class="model-kpis"><div class="model-kpi"><div class="stat-label">Unfunded need · end FY36</div><div class="stat-value">${m(end)}</div><div class="stat-description">${constant?'2026 dollars':'Future dollars'} · after assumed funding</div></div><div class="model-kpi"><div class="stat-label">Unfunded need ÷ indexed CRV</div><div class="stat-value">${result.ratio.toFixed(1)}%</div><div class="stat-description">Financial proxy, not observed condition</div></div><div class="model-kpi"><div class="stat-label">Backlog clears and stays clear</div><div class="stat-value" style="font-size:${result.clearYear?'29':'22'}px">${result.clearYear||'Not by FY36'}</div><div class="stat-description">Within this ten-year planning horizon</div></div></div>
  <section class="panel">${panelHead('Annual renewal need vs. funding',`${constant?'2026 dollars':'Future dollars'} · scheduled need ${m(constant?result.totalBase:result.totalNominal)}`,20)}${annualChart(result)}<p class="subtle-note">FY27 already contains the current backlog; it is counted once. The allocation line is your scenario assumption, not a committed district budget.${constant?' Nominal allocations are converted to 2026 purchasing power.':''}</p></section>
  <section class="panel" style="margin-top:20px">${panelHead('The cost of an unfunded plan','End-of-year unfunded need, including inflation on deferred work')}${backlogChart(result)}<div class="count-line" style="margin:8px 0 0"><span>Additional inflation on deferred work <strong>${m(result.deferralCost)}</strong> in future dollars</span><button class="button text" data-action="export-model">${icon('download')}Export projection</button></div></section>
  ${result.replacementActive?`<div class="notice amber"><strong>Replacement sensitivity case.</strong> Removes Coral Key’s $14.720M renewal profile and adds $1.2M stabilization plus $0.3M interim roof work in FY27, then your ${m(scenario.replacement)} replacement allowance in FY${String(scenario.replacementYear).slice(-2)}. The study fee and post-replacement lifecycle renewals are not priced. This is not the required 30-year options study.</div>`:''}
  <details class="panel model-note" style="margin-top:20px"><summary style="font-weight:600;cursor:pointer;color:var(--ink)">Model assumptions & annual projection</summary><ul><li>Costs are drawn from Figure 12’s two-decimal annual totals. Default renewal need is $209.1M in 2026 dollars; at 4%, scheduled need is about $243.6M before any deferral.</li><li>FY27 is one year after the 2026 cost base. Each year’s scheduled need is escalated to that year. Carried backlog also escalates one year before the next allocation is applied.</li><li>The annual allocation is a flat nominal amount, beginning in your selected year. Unspent funds carry forward without interest. No outside grant, borrowing or energy savings is added automatically.</li><li>The ratio divides remaining unfunded need by $560.9M of replacement value, indexed at the same inflation rate. It holds replacement value constant in real terms, even in replacement scenarios. It is not a prediction of observed condition.</li><li>The model assumes funding can be spent in-year. It excludes construction capacity limits, emergency costs, deterioration beyond inflation, study fees and the unassessed 33 facilities.</li><li>“Clears” means unfunded need reaches zero and remains zero through FY36. “Not by FY36” does not mean it never clears. Priority 1/2 costs are already included, not added to the forecast.</li></ul><div class="table-wrap"><table class="data-table"><thead><tr><th>Year</th><th class="right">New need</th><th class="right">Spent</th><th class="right">Unfunded</th><th class="right">Reserve</th><th class="right">Need / CRV</th></tr></thead><tbody>${result.rows.map(row=>{const f=constant?row.factor:1;return `<tr><td>${row.label}</td><td class="right">${m(row.due/f,2)}</td><td class="right">${m(row.spent/f,2)}</td><td class="right">${m(row.backlog/f,2)}</td><td class="right">${m(row.reserve/f,2)}</td><td class="right">${row.ratio.toFixed(1)}%</td></tr>`}).join('')}</tbody></table></div><p class="subtle-note">Table in ${constant?'2026':'future'} dollars. Exports contain both dollar bases.</p></details>`;
}
function capital(){
  return heading('Capital planning','What does a funded future look like?','Start with the report’s renewal forecast. Adjust the assumptions to see how the funding gap changes over time.',source(20,'Report pp. 20–21'))+
  `<div class="capital-layout">${capitalControls()}<div id="capital-results" aria-live="polite">${capitalOutputs()}</div></div>
  ${section('The work behind the forecast','Report baseline · $209.1M in 2026 dollars',source(21))}<div class="grid-two"><section class="panel">${panelHead('Need by system group','HVAC and envelope represent 54% of the total')}<div class="system-bars" aria-label="System shares of ten-year renewal need">${D.systems.map(s=>`<span style="width:${s.total/209.1*100}%;background:${s.color}" title="${s.name}: ${m(s.total)}"></span>`).join('')}</div>${D.systems.map(s=>`<div class="system-row"><span><i class="dot" style="--dot:${s.color}"></i>${s.name}</span><span>${m(s.total)}</span><span class="muted">${(s.total/209.1*100).toFixed(0)}%</span></div>`).join('')}<p class="subtle-note">Rounded system totals may differ from the published portfolio total.</p></section><section class="panel">${panelHead('A front-loaded capital program','43% of the decade’s need arrives in the first two years')}<div class="stat" style="margin-top:25px"><div class="stat-label">FY27 + FY28 · 2026 dollars</div><div class="stat-value">$88.9M</div><div class="stat-description">Includes $53.3M of current needs in FY27</div></div><div class="stat" style="margin-top:28px"><div class="stat-label">Average renewal after FY27 · eight sites</div><div class="stat-value">$17.3M<span class="small"> / year</span></div><div class="stat-description">Compared with $15.1M renewal capacity for all 41 sites</div></div><p class="subtle-note" style="margin-top:22px">Clearing the backlog is a one-time challenge. Sustaining the renewal cycle requires a continuing budget commitment.</p></section></div>
  <details class="panel model-note"><summary style="cursor:pointer;font-weight:600;color:var(--ink)">Report system schedule · 2026 dollars</summary><div class="table-wrap" style="margin-top:16px"><table class="data-table"><thead><tr><th>System</th>${['FY27','FY28','FY29','FY30','FY31','FY32–36','Total'].map(y=>`<th class="right">${y}</th>`).join('')}</tr></thead><tbody>${D.systems.map(s=>`<tr><td>${s.name}</td>${[...s.years,s.total].map(v=>`<td class="right">${m(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="subtle-note">The report groups FY32–FY36 system values. Annual system splits within those five years are not supplied.</p></details>
  ${section('Three phases, one continuing program','Report baseline; scope and approval timing still govern delivery.',source(40))}${phases()}`;
}

function updateNav(route,siteId){
  const base=route.split('/')[0];
  $('#primary-nav').innerHTML=navs.map(([id,title,i])=>`<a href="#/${id}" class="nav-item ${id===base?'active':''}" ${id===base?'aria-current="page"':''}>${icon(i)}<span>${title}</span></a>${id==='sites'&&base==='sites'?`<div class="sidebar-sites">${D.sites.map(s=>`<a class="${s.id===siteId?'active':''}" href="#/sites/${s.id}">${s.short}</a>`).join('')}</div>`:''}`).join('');
}
function parseRoute(){
  const raw=location.hash.replace(/^#\/?/,'')||'overview',idx=raw.indexOf('?');
  return {route:idx<0?raw:raw.slice(0,idx),params:new URLSearchParams(idx<0?'':raw.slice(idx+1))};
}
function render(scroll=false){
  const {route,params}=parseRoute();currentRoute=route;currentSite=null;
  if(route==='capital'&&params.size)scenario=normalize(Object.fromEntries(params));
  if(route==='action'){
    filters={q:params.get('q')||'',site:siteById(params.get('site'))?params.get('site'):'all',priority:['1','2','3','4'].includes(params.get('priority'))?params.get('priority'):'all',system:D.findings.some(f=>f.system===params.get('system'))?params.get('system'):'all'};
  }
  updateNav(route,route.split('/')[1]);
  const pages={overview,capital,sites,energy,action,funding,about};
  const html=route.startsWith('sites/')?siteDetail(route.split('/')[1]):pages[route]?.()??notFound();
  $('#main').innerHTML=html;
  const title=currentSite?.name||navs.find(n=>n[0]===route)?.[1]||'Assessment';
  document.title=`${title} | Mangrove Bay | Upchurch`;
  $('.nav-shell').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');
  if(scroll){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}
}
function updateFindings(){
  activeFindings=filteredFindings();
  $('#findings-table').innerHTML=findingsTable(activeFindings);$('#finding-count').innerHTML=findingCount(activeFindings);
  $$('[data-priority]').forEach(b=>{const selected=b.dataset.priority===filters.priority;b.classList.toggle('selected',selected);b.setAttribute('aria-pressed',String(selected));});
  const params=new URLSearchParams();for(const [k,v]of Object.entries(filters))if(v&&v!=='all')params.set(k,v);
  history.replaceState(null,'',`#/action${params.size?'?'+params:''}`);
}
function updateCapital(){
  history.replaceState(null,'',`#/capital?${scenarioQuery(scenario)}`);
  $('#capital-results').innerHTML=capitalOutputs();
}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('visible'),3500);}
function downloadCSV(name,headers,rows){
  const csv=[headers,...rows].map(row=>row.map(v=>'"'+String(v??'').replace(/"/g,'""')+'"').join(',')).join('\r\n');
  const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8;'})),a=document.createElement('a');
  a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Export downloaded.');
}
async function shareScenario(){
  const url=location.origin+location.pathname+'#/capital?'+scenarioQuery(scenario);
  try{await navigator.clipboard.writeText(url);toast('Scenario link copied.');}catch{const input=$('#share-url');input.value=url;$('#share-dialog').showModal();input.select();}
}
function exportSites(){
  const sites=D.sites.filter(s=>siteType==='all'||s.type===siteType);
  downloadCSV('mangrove-bay-sites.csv',['Facility','Type','GSF','Built','Renovation','Enrollment','Current needs USD millions','Published FCI percent','Rating','CRV USD millions','Ten-year renewal USD millions','Renewal / CRV percent','Site EUI kBtu/sf','Total utility USD/sf','Flood zone','EHPA shelter','Data cutoff','Sample status'],sites.map(s=>[s.name,s.type,s.area,s.built,s.renovation,s.enrollment,s.current,s.fci,s.rating,s.crv,s.renewal,s.renewalRatio,s.eui,s.utilityCost,s.flood,s.shelter?'Yes':'No',D.cutoff,'Fictional sample']));
}
function exportFindings(){downloadCSV('mangrove-bay-filtered-findings.csv',['ID','Facility','Priority','System','Finding','Scope','Project cost USD 2026','Budget timing','On hold','Report page','Included in renewal forecast','Data cutoff','Sample status'],activeFindings.map(f=>[f.id,siteById(f.site).name,f.priority,f.system,f.title,f.scope,f.cost,f.year,f.hold?'Yes':'No',f.page,'Yes',D.cutoff,'Fictional sample']));}
function exportModel(){
  const result=model(scenario);if(!result.valid){toast(result.error);return;}
  downloadCSV('mangrove-bay-capital-scenario.csv',['Fiscal year','New need 2026 USD','New need future USD','Annual allocation nominal USD','Spent nominal USD','Unfunded need nominal USD','Unfunded need 2026 USD','Reserve nominal USD','Unfunded need / indexed CRV percent','Inflation on deferred work nominal USD','Annual inflation percent','Coral Key pathway','Replacement allowance 2026 USD','Replacement year','Model status'],result.rows.map(r=>[r.label,Math.round(r.base*1e6),Math.round(r.due*1e6),Math.round(r.allocation*1e6),Math.round(r.spent*1e6),Math.round(r.backlog*1e6),Math.round(r.backlog/r.factor*1e6),Math.round(r.reserve*1e6),r.ratio.toFixed(3),Math.round(r.inflationOnBacklog*1e6),scenario.inflation,scenario.coral,scenario.replacement===null?'':Math.round(scenario.replacement*1e6),scenario.coral==='replace'?scenario.replacementYear:'','Illustrative projection; not observed condition']));
}
function setLayout(sidebar){
  document.body.classList.toggle('sidebar',sidebar);const b=$('#layout-toggle');b.innerHTML=icon(sidebar?'tabs':'layout');b.title=sidebar?'Switch to top tab navigation':'Switch to sidebar navigation';b.setAttribute('aria-label',b.title);b.setAttribute('aria-pressed',String(sidebar));
  try{localStorage.setItem('mangrove-navigation',sidebar?'sidebar':'tabs');}catch{}
}
function handleClick(event){
  const b=event.target.closest('button');if(!b)return;
  if(b.dataset.sort){const key=b.dataset.sort;if(siteSort.key===key)siteSort.direction*=-1;else siteSort={key,direction:key==='name'?1:-1};$('#site-table').innerHTML=siteTable();return;}
  if(b.dataset.priority){filters.priority=filters.priority===b.dataset.priority?'all':b.dataset.priority;$('#finding-priority').value=filters.priority;updateFindings();return;}
  if(b.dataset.dollar){scenario.dollars=b.dataset.dollar;updateCapital();return;}
  switch(b.dataset.action){
    case 'export-sites':exportSites();break;
    case 'export-findings':exportFindings();break;
    case 'export-model':exportModel();break;
    case 'share-model':shareScenario();break;
    case 'reset-model':scenario={...defaults};history.replaceState(null,'','#/capital');$('#main').innerHTML=capital();toast('Report assumptions restored.');break;
    case 'clear-filters':filters={q:'',site:'all',priority:'all',system:'all'};history.replaceState(null,'','#/action');$('#main').innerHTML=action();break;
  }
}
function handleInput(event){
  const el=event.target;
  if(el.id==='finding-search'){filters.q=el.value;updateFindings();return;}
  if(!el.dataset.scenario||el.tagName==='SELECT')return;
  const key=el.dataset.scenario;
  if(el.value===''&&key!=='replacement')return;
  const candidate={...scenario,[key]:el.value===''?null:Number(el.value)};scenario=normalize(candidate);
  if(key==='funding'||key==='inflation'){
    const partner=$(`#${key}-${el.type==='range'?'input':'range'}`);if(partner)partner.value=scenario[key];
  }
  updateCapital();
}
function handleChange(event){
  const el=event.target;
  if(el.id==='site-type'){siteType=el.value;$('#site-table').innerHTML=siteTable();return;}
  if(el.id==='site-switcher'){location.hash='#/sites/'+el.value;return;}
  const map={'finding-site':'site','finding-priority':'priority','finding-system':'system'};
  if(map[el.id]){filters[map[el.id]]=el.value;updateFindings();return;}
  if(el.dataset.scenario){
    const key=el.dataset.scenario;
    scenario=normalize({...scenario,[key]:el.value===''?null:el.value});
    if(key==='coral'){
      history.replaceState(null,'',`#/capital?${scenarioQuery(scenario)}`);$('#main').innerHTML=capital();
    }else{
      if(el.type==='number')el.value=scenario[key]??'';
      updateCapital();
    }
  }
}
function init(){
  $('#download-icon').innerHTML=icon('download');$('#print-view').innerHTML=icon('print');$('#menu-toggle').innerHTML=icon('menu');
  $('#print-view').addEventListener('click',()=>window.print());
  $('#menu-toggle').addEventListener('click',()=>{const open=$('.nav-shell').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Close navigation':'Open navigation');});
  $('#main').addEventListener('click',handleClick);$('#main').addEventListener('input',handleInput);$('#main').addEventListener('change',handleChange);
  window.addEventListener('hashchange',()=>render(true));
  window.addEventListener('keydown',event=>{if(event.key==='Escape'){$('.nav-shell').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
  render();
}
if(typeof document!=='undefined')init();
// Pure render functions are exported for source and coverage verification without a browser dependency.
export {overview,sites,siteDetail,energy,action,funding,about,capital,findingsTable,quadrant,portfolioMap,esc};
